        }

        double num = Double.parseDouble(value);
        int result = 0;
        if (value.substring(value.length() - 2).equals(".5")) {
            result = num > 0 ? (int)Math.floor(num) : (int)Math.ceil(num);
        } else if (value.length() > 0){
            result = (int)Math.round(num);
        }

        return result;
    }
}

