//     the number of remaining carrots thet exist in stock

// Constrain:
// * 0 <= number <= 1000
// * 0 <= need <= 1000
// * 0 <= remaining <= 1000

// Have fun :)

public class EAT {
    public static int[] eat(int number, int need, int remaining) {
        return new int[] {number + need,  remaining - need};
    }
}

