        for(int i = new_s.length() - 1; i >= 0; i--) {
            reverse_s += new_s.charAt(i);
        }
        ArrayList<Object> res = new ArrayList<>();
        res.add(new_s);
        res.add(reverse_s.equals(new_s));
        return res;
    }
}

