    public static boolean valid_date(String date) {
        try {
            date = date.trim();
            String[] date_info = date.split("-");
            if(date_info.length > 3) return false;
            int month = Integer.parseInt(date_info[0]);
            int day = Integer.parseInt(date_info[1]);
