            for(int i = 0; i < month_check2.length; i++) {
                if(month == month_check2[i] && (day < 1 || day > 30)) return false;
            }
            if(month == 2 && (day < 1 || day > 29)) return false;
        } catch (Exception e) {
            return false;
        }
        return true;
    }
}

